const b=$json.body??$json;
const rows=Array.isArray(b.campaigns)?b.campaigns:[b];
if(!rows.length) throw new Error("Provide at least one campaign in campaigns[].");
const reportEmail=String(b.report_email??"").trim();
const campaigns=rows.map((r,i)=>{
  const impressions=Number(r.impressions);
  const clicks=Number(r.clicks);
  const conversions=Number(r.conversions);
  const spend=Number(r.spend);
  const revenue=r.revenue===undefined?null:Number(r.revenue);
  if(![impressions,clicks,conversions,spend].every(Number.isFinite) || impressions<0 || clicks<0 || conversions<0 || spend<0) {
    throw new Error(`Campaign ${i+1} has missing or invalid numeric metrics.`);
  }
  if(clicks>impressions) throw new Error(`Campaign ${i+1}: clicks cannot exceed impressions.`);
  if(conversions>clicks) throw new Error(`Campaign ${i+1}: conversions cannot exceed clicks.`);
  return {
    campaign_name:String(r.campaign_name??`Campaign ${i+1}`),
    platform:String(r.platform??"Not specified"),
    impressions,clicks,conversions,spend,
    revenue,
    ctr_percent:impressions?Number((clicks/impressions*100).toFixed(2)):0,
    conversion_rate_percent:clicks?Number((conversions/clicks*100).toFixed(2)):0,
    cpa:conversions?Number((spend/conversions).toFixed(2)):null,
    cpm:impressions?Number((spend/impressions*1000).toFixed(2)):null,
    roas:revenue!==null&&spend>0?Number((revenue/spend).toFixed(2)):null
  };
});
return [{json:{report_email:reportEmail,report_period:String(b.report_period??"Not specified"),currency:String(b.currency??"USD"),campaigns}}];

function parseContent(value){
 if(typeof value!=="string") return value;
 return JSON.parse(value.trim().replace(/^```(?:json)?\s*/i,"").replace(/\s*```$/,""));
}
const content=$json.choices?.[0]?.message?.content;
if(!content) throw new Error("No AI analysis returned.");
const analysis=parseContent(Array.isArray(content)?content.map(x=>x.text??"").join("\n"):content);
const source=$("Validate Data & Calculate KPIs").first().json;
for(const key of ["executive_summary","campaign_insights","risks","next_actions","data_limitations"]){
 if(analysis[key]===undefined) throw new Error(`AI report missing ${key}`);
}
return [{json:{
 success:true,
 report_period:source.report_period,
 currency:source.currency,
 campaigns:source.campaigns,
 analysis,
 generated_at:new Date().toISOString(),
 disclaimer:"AI-generated observations are decision support, not proof of causation. Verify platform attribution and tracking before making budget decisions."
}}];
